"""Exercise the real HTTP request generated by the remote workbench transport."""
from __future__ import annotations

from contextlib import redirect_stdout
import io
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import threading
import unittest
from unittest.mock import patch

from scripts.stage1_drl_r04 import ops


class _Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        return

    def _respond(self, value):
        payload = json.dumps(value).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_GET(self):
        self._respond({"method": "GET", "path": self.path})

    def do_POST(self):
        payload = self.rfile.read(int(self.headers["Content-Length"]))
        self._respond({"method": "POST", "path": self.path,
                       "body": json.loads(payload)})


class DrlR04OpsHttpTests(unittest.TestCase):
    def test_body_selects_post_and_empty_body_selects_get(self):
        server = ThreadingHTTPServer(("127.0.0.1", 0), _Handler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        self.addCleanup(server.server_close)
        self.addCleanup(server.shutdown)

        def execute_locally(code, port, timeout=120):
            output = io.StringIO()
            with redirect_stdout(output):
                exec(code, {})
            return {"exit_code": 0, "stdout": output.getvalue(), "stderr": ""}

        with patch.dict(ops.API_PORTS, {20418: server.server_port}), \
                patch.object(ops, "remote_python", side_effect=execute_locally):
            posted = ops.api(20418, "/api/coverage/runs", {"kind": "train"})
            fetched = ops.api(20418, "/api/coverage/catalog")
        self.assertEqual(posted, {"method": "POST", "path": "/api/coverage/runs",
                                  "body": {"kind": "train"}})
        self.assertEqual(fetched, {"method": "GET", "path": "/api/coverage/catalog"})


if __name__ == "__main__":
    unittest.main()
